        correctChoice: 'B',
        justifications: [
          { id: 'j1', text: 'Interval-by-interval IOA = agreements ÷ (agreements + disagreements) × 100 = 7 ÷ (7+3) × 100 = 7 ÷ 10 × 100 = 70%.', isCorrect: true, justifiesChoice: 'B' },
          { id: 'j2', text: 'There are 10 total intervals (7 agreements + 3 disagreements), and 7 of those were agreed upon, yielding 70%.', isCorrect: true, justifiesChoice: 'B' },
          { id: 'j3', text: '70% falls below the commonly accepted criterion of ≥ 80%, indicating the IOA is inadequate and retraining or recalibration of observers is warranted.', isCorrect: true, justifiesChoice: 'B' },
          { id: 'j4', text: 'IOA = agreements ÷ total intervals = 7 ÷ 12 = 58%, because there are 12 intervals in a 2-minute session.', isCorrect: false, justifiesChoice: 'A' },
          { id: 'j5', text: 'IOA = (agreements - disagreements) ÷ agreements × 100 = (7-3) ÷ 7 × 100 = 57%, rounded to 58%.', isCorrect: false, justifiesChoice: 'A' },
          { id: 'j6', text: 'IOA = agreements ÷ (agreements + disagreements + 1) × 100 = 7 ÷ 11 × 100 = 64%, rounded to 77% after adjustment.', isCorrect: false, justifiesChoice: 'C' },
          { id: 'j7', text: 'IOA = (total intervals - disagreements) ÷ total intervals × 100 = (12-3) ÷ 12 × 100 = 75%, rounded to 77%.', isCorrect: false, justifiesChoice: 'C' },
          { id: 'j8', text: 'IOA = agreements ÷ (agreements + 0.5 × disagreements) × 100 = 7 ÷ 8.5 × 100 = 82%, rounded to 85%.', isCorrect: false, justifiesChoice: 'D' },
          { id: 'j9', text: 'IOA = (agreements × 2) ÷ (total intervals × 2) × 100 = 14 ÷ 20 × 100 = 70%, but the standard formula gives 85%.', isCorrect: false, justifiesChoice: 'D' },
        ],
        explanation: 'Interval-by-interval IOA = agreements ÷ (agreements + disagreements) × 100 = 7 ÷ 10 × 100 = 70%. This is below the 80% criterion, indicating the observers need recalibration before data collection continues.',
